const ids=new Map()
for(const [collection,rows] of Object.entries(data))if(Array.isArray(rows))for(const row of rows)if(row.id){if(ids.has(row.id))throw new Error(`Duplicate id ${row.id}`);ids.set(row.id,collection)}
const assertRef=(value,rows,label)=>{if(value!=null&&!new Set(rows.map(r=>r.id)).has(value))throw new Error(`${label}: missing ${value}`)}
events.forEach(e=>{assertRef(e.chapterId,chapters,`${e.id}.chapter`);assertRef(e.locationMarkerId,locationMarkers,`${e.id}.location`);e.involvedCharacterIds.forEach(v=>assertRef(v,characters,`${e.id}.character`));e.involvedItemIds.forEach(v=>assertRef(v,items,`${e.id}.item`));e.threadIds.forEach(v=>assertRef(v,plotThreads,`${e.id}.thread`));e.motifIds.forEach(v=>assertRef(v,motifs,`${e.id}.motif`));if(!Number.isInteger(e.tension)||e.tension<1||e.tension>5)throw new Error(`${e.id}: tension`);if(!Number.isFinite(e.travelDays)||e.travelDays<0)throw new Error(`${e.id}: elapsed time`)})
for(const e of events){const snaps=characterSnapshots.filter(s=>s.eventId===e.id);if(snaps.length!==e.involvedCharacterIds.length)throw new Error(`${e.id}: snapshot count`);if(new Set(snaps.map(s=>s.statusNotes.toLowerCase())).size!==snaps.length)throw new Error(`${e.id}: repeated snapshot state`)}
if(chapters.length!==117||new Set(events.map(e=>e.chapterId)).size!==117)throw new Error('Every chapter must have events')
mapLayers.forEach(m=>assertRef(m.imageId,blobs,`${m.id}.image`));locationMarkers.forEach(l=>{assertRef(l.mapLayerId,mapLayers,`${l.id}.map`);assertRef(l.linkedMapLayerId,mapLayers,`${l.id}.linkedMap`);assertRef(l.imageId,blobs,`${l.id}.image`)});characters.forEach(c=>assertRef(c.portraitImageId,blobs,`${c.id}.portrait`));items.forEach(i=>assertRef(i.imageId,blobs,`${i.id}.image`))

